// 1. Daten aus den möglichen Variablen beziehen
let rawData = this.output || this.items || this.final_output || {};

// Falls rawData ein Array ist, verwende den ersten Eintrag
if (Array.isArray(rawData)) {
    rawData = rawData[0];
}

// Falls rawData als String vorliegt, versuche ihn zu parsen
if (typeof rawData === "string") {
    try {
        rawData = JSON.parse(rawData);
    } catch (e) {
        return [{ text: "Fehler: JSON-Parsing fehlgeschlagen." }];
    }
}

// 2. (Hinweis: Der Teil, der auf {"json": {"output": [ ... prüft, wurde entfernt)

// 3. Text extrahieren
if (!rawData.text || typeof rawData.text !== "string") {
    return [{
      text: JSON.stringify(rawData, null, 2)
    }];
}
let finalText = rawData.text;

// 4. Falls noch Escape-Sequenzen vorhanden sind, versuche sie mit JSON.parse zu decodieren
if (finalText.indexOf("\\n") !== -1) {
    try {
        // Wandelt \n-Escape-Sequenzen in echte Newlines um
        finalText = JSON.parse('"' + finalText.replace(/"/g, '\\"') + '"');
    } catch (e) {
        // Fallback: einfache Ersetzung
        finalText = finalText.replace(/\\n/g, "\n");
    }
}

// 5. Erzwinge, dass zwischen Absätzen doppelte Newlines stehen (Markdown-Anforderung)
finalText = finalText.replace(/\n(?!\n)/g, "\n\n");

// 6. Gib ausschließlich ein Objekt mit dem text-Feld zurück
return [{ text: finalText.trim() }];

// 1. Daten aus den möglichen Variablen beziehen
let rawData = this.output || this.items || this.final_output || {};
if (Array.isArray(rawData)) {
    rawData = rawData[0];
}
if (rawData.json) {
    rawData = rawData.json;
}

// 2. Falls rawData ein output-Feld enthält (als Array), extrahiere den ersten Eintrag
if (rawData.output && Array.isArray(rawData.output) && rawData.output.length > 0) {
    let outputStr = rawData.output[0];
    if (typeof outputStr === "string") {
        // Ersetze unescapete Newlines durch korrekte Escape-Sequenzen
        outputStr = outputStr.replace(/\r?\n/g, "\\n");
        try {
            rawData = JSON.parse(outputStr);
        } catch (e) {
            return [{ text: "Fehler: JSON-Parsing des output-Feldes fehlgeschlagen." }];
        }
    } else {
        rawData = rawData.output[0];
    }
}

// 3. Text extrahieren
if (!rawData.text || typeof rawData.text !== "string") {
    return [{ text: "Fehler: Kein `text`-Eintrag gefunden.\nDebug-Info:\n" + JSON.stringify(rawData, null, 2) }];
}
let finalText = rawData.text;

// 4. Escape-Sequenzen in echte Newlines umwandeln
finalText = finalText.replace(/\\n/g, "\n");

// 5. Erzwinge, dass zwischen einzelnen Newlines doppelte Newlines stehen
finalText = finalText.replace(/\n(?!\n)/g, "\n\n");

// 6. Nur den Text ab "### Einleitung" verwenden (falls vorhanden)
let startIndex = finalText.indexOf("### Einleitung");
if (startIndex !== -1) {
    finalText = finalText.substring(startIndex);
}

// 7. Entferne alle verbleibenden Backslashes
finalText = finalText.replace(/\\/g, "");

// 8. Gib ausschließlich ein JSON-Objekt mit dem text-Feld zurück
return [{ text: finalText.trim() }];

